import sympy

def is_square(n):
    if n < 0: return False
    sqrt_n = int(n**0.5)
    return sqrt_n * sqrt_n == n

def check_solutions(a, b, c, range_limit=100):
    solutions = []
    for x in range(-range_limit, range_limit + 1):
        val = x**3 + a*x**2 + b*x + c
        if is_square(val):
            solutions.append(x)
    return solutions

# We want solutions to be exactly [0, 1]
# Q(0) = c = k^2
# Q(1) = 1 + a + b + c = m^2

results = []
for k in range(0, 10):
    for m in range(0, 10):
        c = k*k
        # 1 + a + b + c = m^2  => b = m^2 - c - 1 - a
        for a in range(-10, 11):
            b = m*m - c - 1 - a
            sols = check_solutions(a, b, c)
            if sols == [0, 1]:
                results.append((k, m, a, b, c))

print(results)

